const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : input;
const allowedActions = ['login_success', 'logout'];
if (!allowedActions.includes(body.action)) throw new Error('Tipo de evento de sesión no permitido.');
if (!String(body.userId || '').trim()) throw new Error('El evento debe incluir userId.');
const now = new Date().toISOString();
const duration = body.durationSeconds === null || body.durationSeconds === undefined || body.durationSeconds === '' ? null : Number(body.durationSeconds);
return [{ json: {
  eventId: String(body.eventId || `activity-${Date.now()}`),
  action: body.action,
  description: String(body.description || ''),
  userId: String(body.userId),
  userName: String(body.userName || ''),
  userEmail: String(body.userEmail || ''),
  role: String(body.role || ''),
  roleLabel: String(body.roleLabel || ''),
  module: String(body.module || 'authentication'),
  sessionId: String(body.sessionId || ''),
  sessionStartedAt: body.sessionStartedAt || null,
  sessionEndedAt: body.sessionEndedAt || null,
  durationSeconds: Number.isFinite(duration) ? duration : null,
  userAgent: String(body.userAgent || ''),
  language: String(body.language || ''),
  timeZone: String(body.timeZone || ''),
  occurredAt: body.occurredAt || now,
  createdAt: now
} }];
